import com.sun.jdi.*;import com.sun.jdi.connect.*;import com.sun.jdi.event.*;import com.sun.jdi.request.*;import java.util.*;
public class JdiExec2{
 static Method find(ReferenceType t,String n,String s){for(Method m:t.methodsByName(n))if(m.signature().equals(s))return m;return null;}
 static void ex(InvocationException ie){ObjectReference e=ie.exception();System.out.println("EX "+e.referenceType().name());try{Field f=e.referenceType().fieldByName("detailMessage");if(f!=null)System.out.println(" msg="+e.getValue(f));}catch(Throwable t){}}
 public static void main(String[] a)throws Exception{String cmd=a[0];AttachingConnector conn=null;for(AttachingConnector c:Bootstrap.virtualMachineManager().attachingConnectors())if(c.name().equals("com.sun.jdi.SocketAttach"))conn=c;Map<String,Connector.Argument> ca=conn.defaultArguments();ca.get("hostname").setValue("localhost");ca.get("port").setValue("8700");ca.get("timeout").setValue("5000");VirtualMachine vm=conn.attach(ca);
 try{ReferenceType svc=vm.classesByName("com.cvte.factory.service.MainService").get(0);Method on=find(svc,"onStartCommand","(Landroid/content/Intent;II)I");BreakpointRequest bp=vm.eventRequestManager().createBreakpointRequest(on.location());bp.setSuspendPolicy(EventRequest.SUSPEND_EVENT_THREAD);bp.enable();Thread t=new Thread(()->{try{Thread.sleep(1200);new ProcessBuilder("adb","-s","<TV_IP>:5555","shell","am","startservice","-n","com.cvte.factory.service/.MainService","-a","cvte.factory.intent.action.APIInit").inheritIO().start().waitFor();}catch(Exception e){e.printStackTrace();}});t.start();vm.resume();EventSet es=vm.eventQueue().remove(15000);ThreadReference thr=null;if(es!=null)for(Event ev:es)if(ev instanceof BreakpointEvent)thr=((BreakpointEvent)ev).thread();if(thr==null){System.out.println("no bp");vm.resume();return;}
 ReferenceType rt=vm.classesByName("java.lang.Runtime").get(0);Value r=rt.getValue(rt.fieldByName("currentRuntime"));ObjectReference run=(ObjectReference)r;Method exec=find(rt,"exec","(Ljava/lang/String;)Ljava/lang/Process;");try{Value p=run.invokeMethod(thr,exec,Collections.singletonList(vm.mirrorOf(cmd)),0);System.out.println("exec="+p);}catch(InvocationException ie){ex(ie);}bp.disable();vm.resume();}finally{vm.dispose();}}
}
